<template>
    <form @submit.prevent="submitEntry()">
       <div class="row">

    <!-- Show Asset only when groupId exists -->
    <div v-if="props.groupId" class="col-md-4">
        <label class="form-label">Select Machine/Vehicle</label>

        <Multiselect
            v-model="formData.asset"
            :options="assets"
            label="name"
            placeholder="Select an item"
            :searchable="true"
            :allow-empty="false"
        />
    </div>

    <div :class="props.groupId ? 'col-md-4' : 'col-md-6'">
        <label class="form-label">Description</label>
        <input
            class="form-control"
            type="text"
            v-model="formData.description"
            placeholder="Work Done / Activity done"
        >
    </div>

    <div :class="props.groupId ? 'col-md-4' : 'col-md-2'">
        <label class="form-label">Enter Quantity; Available {{props.qtyBalance}}</label>
        <input
            class="form-control"
            type="number"
            step="any"
            placeholder="Qty Issued"
            v-model="formData.quantity"
            required
           @input="formData.quantity = enforceMax(formData.quantity, props.qtyBalance)"
        >
    </div>

    <!-- Rate only for non-group expenses -->
    <div v-if="!props.groupId" class="col-md-2">
        <label class="form-label">Enter Rate</label>
        <input
            class="form-control"
            type="number"
            step="any"
            placeholder="Rate"
            v-model="formData.rate"
        >
    </div>

    <!-- Initial Odometer -->
    <div v-if="props.groupId" class="col-md-4 mt-2">
        <label class="form-label">Initial Odometer Reading</label>
        <input
            class="form-control"
            type="number"
            step="any"
            min="0"
            placeholder="Initial Odometer"
            v-model="formData.initial_reading"
        >
    </div>

    <!-- Final Odometer -->
    <div v-if="props.groupId" class="col-md-4 mt-2">
        <label class="form-label">Final Odometer Reading</label>
        <input
            class="form-control"
            type="number"
            step="any"
            :min="formData.initial_odometer || 0"
            placeholder="Final Odometer"
            v-model="formData.final_reading"
        >
    </div>

    <!-- Date -->
    <div :class="props.groupId ? 'col-md-4 mt-2' : 'col-md-2'">
        <label class="form-label">Date</label>
        <input
            class="form-control"
            type="date"
            v-model="formData.date"
        >
    </div>

    <!-- Buttons -->
    <div class="d-flex mt-3">
        <div class="ms-auto">
            <button
                type="button"
                class="btn btn-danger me-2"
                @click="closeForm"
            >
                Close
            </button>

            <button
                type="submit"
                class="btn btn-primary"
                :disabled="loading"
            >
                <span
                    v-if="loading"
                    v-html="loadingSpinner()"
                ></span>

                <span v-else>Save</span>
            </button>
        </div>
    </div>

</div>
    </form>
</template>

<script setup>
import { ref, onMounted, watch, inject } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect'
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css'
const enforceMax = inject('enforceMax')
const user_id = JSON.parse(localStorage.getItem("user")).id
const loadingSpinner = inject('loadingSpinner')
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
const showMessage = inject('showMessage')
const showError = inject('showError')

const assets = ref([])
const group_id = ref(props.groupId)
const getAssets = async ()=>{
   const response = await axiosInstance.get(`machine-and-vehicles?group_id=${group_id.value}`)
   assets.value = response.data.map((item)=>({
     ...item,
     name : item.name + ' - '+ item.category
   }))
}

const formData = ref({
    id : '',
    asset : '',
    quantity : '',
    date : '',
    description : '',
    rate : '',
    initial_odometer: '',
    final_odometer: '',
})

const fillForm = ref(false)
const clearForm = ()=>{
    fillForm.value = false
    formData.value = {
    id : '',
    asset : '',
    quantity : '',
    date : '',
    description : '',
    initial_odometer: '',
    final_odometer: '',


}
}

onMounted(() => {
 getAssets()
})



const props = defineProps({
    groupId: String,
    parentId : String,
    entryId : String,
    rateValue: Number,
    qtyBalance:Number
});


watch(() => props.groupId, (newId) => {
    if(newId){
        group_id.value = newId
        getAssets()
    }
})

const emit = defineEmits(["saved", "close"]);
const loading = ref(false)
const submitEntry = async ()=>{
    loading.value = true
     const hasGroup = !!props.groupId
    const payload = {
      entry_id : props.entryId,
      rate :  hasGroup ? props.rateValue  : formData.value.rate ,
      parent_id: props.parentId,
      quantity : formData.value.quantity,
      initial_reading:formData.value.initial_reading,
      final_reading:formData.value.final_reading,
      issuer_id:user_id,
      source: hasGroup ? 'assets' : null,
        source_id: hasGroup
            ? formData.value.asset?.id ?? null
            : null,
      date : formData.value.date,
      description : formData.value.description,
    unit_id:hasGroup ? 25 : null,
    }

     try{
         const response = await axiosInstance.post('store-project-expense-items',payload)
         showMessage('Data Saved')
             emit("saved")
         clearForm()
      }catch(error){
        showError(error.message)
        console.log(error)
     }finally{
       loading.value = false
     }
}

const closeForm = () => {
    clearForm()
    emit("close")
}

</script>